-- TEST71 FOC + targeted push substantive parity
create table if not exists public.rr_foc_policy_v704(id uuid primary key default gen_random_uuid(),code text not null unique,label text not null,rate_per_pc numeric not null check(rate_per_pc>=0),is_active boolean not null default true,updated_at timestamptz not null default now());
insert into public.rr_foc_policy_v704(code,label,rate_per_pc) values('ELECTRICITY','Electricity',1.50),('THREAD','Thread',1.50),('WATER','Water',0.50),('REPAIRS','Repairs',1.00),('LAPSE_SALARY','Lapse Salary',1.00) on conflict(code) do update set label=excluded.label,rate_per_pc=excluded.rate_per_pc,is_active=true,updated_at=now();
create table if not exists public.rr_targeted_push_outbox_v708(id uuid primary key default gen_random_uuid(),event_key text not null,recipient_worker_id uuid not null,title text not null,body text not null,route_url text,payload jsonb not null default '{}'::jsonb,dispatch_token uuid not null default gen_random_uuid(),processed_at timestamptz,created_at timestamptz not null default now(),unique(event_key,recipient_worker_id));
create table if not exists public.rr_foc_monthly_summary_v706(period_start date not null,data_mode text not null,eligible_pcs numeric not null default 0,summary jsonb not null,created_at timestamptz not null default now(),primary key(period_start,data_mode));
create or replace function public.rr_foc_cost_v705(p_pcs numeric) returns jsonb language sql stable security definer set search_path to 'public' as $function$ select jsonb_build_object('ok',true,'version','V705_FOC_RECOVERY','head','FOC','rows',coalesce(jsonb_agg(jsonb_build_object('code',code,'label',label,'rate_per_pc',rate_per_pc,'recovered_amount',round(rate_per_pc*p_pcs,2)) order by code),'[]'),'total_rate_per_pc',coalesce(sum(rate_per_pc),0),'eligible_pcs',p_pcs,'total_recovered',round(coalesce(sum(rate_per_pc),0)*p_pcs,2),'rule','FOC IS PRODUCT-COST RECOVERY; ACTUAL INCURRED IS SEPARATE MANAGEMENT SOURCE; GAP ANALYSIS MUST NOT TREAT MISSING ACTUAL AS ZERO') from public.rr_foc_policy_v704 where is_active $function$;
create or replace function public.rr_push_worker_id_v712(p_profile_id uuid) returns uuid language sql stable security definer set search_path to 'public' as $function$ select w.worker_id from public.rr_user_profiles p join public.rr_worker_directory_unified_v1 w on w.linked_auth_user_id=p.auth_user_id where p.id=p_profile_id order by w.is_active desc limit 1 $function$;
create or replace function public.rr_real_chat_route_v713(p_lane text,p_lot_no text default null,p_action text default null) returns text language sql immutable as $function$ select 'test70-cb-purchase-real-chat-pilot.html?rc_status=OPEN&rc_view=chat&rc_kind=group&rc_id='||upper(coalesce(p_lane,'ADMIN'))||'&rc_parent='||upper(coalesce(p_lane,'ADMIN'))||case when p_lot_no is null then '' else '&rc_lot='||p_lot_no end||case when p_action is null then '' else '&rc_action='||p_action end $function$;
